// SPDX-License-Identifier: MIT
pragma solidity 0.8.21;

import {AggregatorV3Interface} from "./interfaces/AggregatorV3Interface.sol";

interface IERC4626 {
    function convertToAssets(uint256 shares) external view returns (uint256 assets);
}

contract ChainlinkOracle {
    IERC4626 public immutable VAULT;
    uint256 public immutable VAULT_CONVERSION_SAMPLE;
    AggregatorV3Interface public immutable BASE_FEED_1;
    AggregatorV3Interface public immutable BASE_FEED_2;
    AggregatorV3Interface public immutable QUOTE_FEED_1;
    AggregatorV3Interface public immutable QUOTE_FEED_2;
    uint256 public immutable SCALE_FACTOR;

    constructor(
        IERC4626 vault,
        AggregatorV3Interface baseFeed1,
        AggregatorV3Interface baseFeed2,
        AggregatorV3Interface quoteFeed1,
        AggregatorV3Interface quoteFeed2,
        uint256 vaultConversionSample,
        uint256 baseTokenDecimals,
        uint256 quoteTokenDecimals
    ) {
        VAULT = vault;
        VAULT_CONVERSION_SAMPLE = vaultConversionSample;
        BASE_FEED_1 = baseFeed1;
        BASE_FEED_2 = baseFeed2;
        QUOTE_FEED_1 = quoteFeed1;
        QUOTE_FEED_2 = quoteFeed2;
        SCALE_FACTOR = 10 ** (36 + quoteTokenDecimals - baseTokenDecimals);
    }

    function _feedPrice(AggregatorV3Interface feed) internal view returns (uint256) {
        if (address(feed) == address(0)) return 1;
        (, int256 answer, , , ) = feed.latestRoundData();
        require(answer > 0, "Oracle: invalid price");
        return uint256(answer);
    }

    function price() external view returns (uint256) {
        uint256 vaultAssets = address(VAULT) == address(0) ? 1 : VAULT.convertToAssets(VAULT_CONVERSION_SAMPLE);
        return (SCALE_FACTOR * vaultAssets * _feedPrice(BASE_FEED_1) * _feedPrice(BASE_FEED_2))
            / (_feedPrice(QUOTE_FEED_1) * _feedPrice(QUOTE_FEED_2));
    }
}

